WITH supplier_stats AS (SELECT supplier_id, MAX(stock_qty) AS max_stock_qty, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list FROM products WHERE price > 970 GROUP BY supplier_id) SELECT s.id, s.country, s.city, ss.max_stock_qty, ss.brand_list FROM suppliers s INNER JOIN supplier_stats ss ON s.id = ss.supplier_id WHERE ss.max_stock_qty >= 310 ORDER BY ss.max_stock_qty DESC, id ASC LIMIT 50
